package io.atlas.api;
import io.atlas.api.auth.service.*;import io.atlas.api.mail.MailOutbox;
import java.util.*;import java.net.*;import java.net.http.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.web.server.LocalServerPort;import org.springframework.test.context.*;import org.springframework.jdbc.core.JdbcTemplate;import tools.jackson.databind.ObjectMapper;
import static org.assertj.core.api.Assertions.*;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties="atlas.core.key=isolated-test-key-never-used-outside-tests-0123456789")
@ActiveProfiles("test")
class MinecraftRecoveryIntegrationTest {
 @DynamicPropertySource static void database(DynamicPropertyRegistry r){TestDatabase.properties(r);}
 @Autowired JdbcTemplate db;@Autowired RecoveryEmailService emails;@Autowired MinecraftRecoveryService recovery;@Autowired MailOutbox mail;@Autowired ObjectMapper json;@LocalServerPort int port;
 UUID player;String email;@BeforeEach void fixture(){player=UUID.randomUUID();email=player+"@example.invalid";db.update("DELETE FROM atlas_web.auth_rate_limits");}
 String code(String subject){return db.queryForList("SELECT encrypted_payload FROM atlas_web.mail_outbox WHERE status='PENDING' ORDER BY created_at DESC",String.class).stream().map(mail::read).filter(m->m.to().equals(email)&&m.subject().contains(subject)).map(m->m.text().split("Código: ")[1].substring(0,8)).findFirst().orElseThrow();}
 void enroll(){emails.request(player,email);assertThat(emails.confirm(player,code("Confirme"))).isTrue();}
 @Test void emailNeedsConfirmationBeforeRecoveryAndWrongAttemptsPersist(){emails.request(player,email);assertThat(emails.configured(player)).isFalse();String actual=code("Confirme");for(int i=0;i<5;i++)assertThat(emails.confirm(player,actual.equals("00000000")?"11111111":"00000000")).isFalse();assertThat(emails.confirm(player,actual)).isFalse();assertThat(db.queryForObject("SELECT attempts FROM atlas_web.minecraft_recovery_email WHERE minecraft_uuid=?",Integer.class,player)).isEqualTo(5);}
 @Test void confirmedEmailAllowsSingleUseCodeBoundToPlayer(){enroll();assertThat(emails.configured(player)).isTrue();recovery.request(player);String secret=code("Recupere");assertThat(recovery.verify(UUID.randomUUID(),secret)).isFalse();assertThat(recovery.verify(player,secret)).isTrue();assertThat(recovery.verify(player,secret)).isFalse();String stored=db.queryForObject("SELECT code_hash FROM atlas_web.minecraft_password_recovery WHERE minecraft_uuid=?",String.class,player);assertThat(stored).doesNotContain(secret);}
 @Test void recoveryExpiresAndLimitsAttempts(){enroll();recovery.request(player);String actual=code("Recupere");for(int i=0;i<5;i++)assertThat(recovery.verify(player,actual.equals("00000000")?"11111111":"00000000")).isFalse();assertThat(recovery.verify(player,actual)).isFalse();recovery.request(player);actual=code("Recupere");db.update("UPDATE atlas_web.minecraft_password_recovery SET expires_at=NOW()-INTERVAL '1 second' WHERE minecraft_uuid=?",player);assertThat(recovery.verify(player,actual)).isFalse();}
 @Test void pendingEmailChangePreservesOldEmailAndConfirmationInvalidatesOldRecovery(){enroll();recovery.request(player);String previousCode=code("Recupere");String previousEmail=email;email="new-"+email;emails.request(player,email);assertThat(db.queryForObject("SELECT email FROM atlas_web.minecraft_recovery_email WHERE minecraft_uuid=?",String.class,player)).isEqualTo(previousEmail);assertThat(emails.confirm(player,code("Confirme"))).isTrue();assertThat(recovery.verify(player,previousCode)).isFalse();}
 @Test void unlinkedUnverifiedPlayerDoesNotSendEmail(){int before=db.queryForObject("SELECT count(*) FROM atlas_web.mail_outbox",Integer.class);recovery.request(player);assertThat(db.queryForObject("SELECT count(*) FROM atlas_web.mail_outbox",Integer.class)).isEqualTo(before);}
 @Test void internalEndpointsRejectMissingKeyAndAcceptOnlyFixedEmailTemplate()throws Exception{
  var client=HttpClient.newHttpClient();String base="http://127.0.0.1:"+port+"/internal/v1/minecraft/password-recovery/email/request";String body=json.writeValueAsString(Map.of("player",player,"email",email));
  var denied=client.send(HttpRequest.newBuilder(URI.create(base)).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());assertThat(denied.statusCode()).isEqualTo(403);
  var allowed=client.send(HttpRequest.newBuilder(URI.create(base)).header("Content-Type","application/json").header("X-Atlas-Key","isolated-test-key-never-used-outside-tests-0123456789").POST(HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());assertThat(allowed.statusCode()).withFailMessage(allowed.body()).isEqualTo(202);assertThat(code("Confirme")).matches("[0-9]{8}");
 }
}
